-- ------------------------------------------------------------
-- EXTENSIONS
-- ------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ------------------------------------------------------------
-- ENUMS
-- ------------------------------------------------------------
DO $$ BEGIN
    CREATE TYPE user_role AS ENUM ('Admin', 'Editor', 'Writer');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE portal_type AS ENUM ('admin', 'writer');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ------------------------------------------------------------
-- TABLE: users
-- ------------------------------------------------------------
CREATE TABLE users (
    id              BIGSERIAL PRIMARY KEY,
    user_id         TEXT NOT NULL UNIQUE,          -- '001', '002', ...
    full_name       TEXT NOT NULL,
    role            user_role NOT NULL DEFAULT 'Writer',
    password_hash   TEXT NOT NULL,                 -- bcrypt from password_hash()
    avatar          TEXT DEFAULT '',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_users_role ON users(role);
CREATE INDEX idx_users_user_id ON users(user_id);

-- ------------------------------------------------------------
-- TABLE: articles
-- ------------------------------------------------------------
CREATE TABLE articles (
    id                  BIGSERIAL PRIMARY KEY,
    title               TEXT NOT NULL,
    slug                TEXT NOT NULL UNIQUE,
    category            TEXT NOT NULL,
    excerpt             TEXT NOT NULL,
    content             TEXT NOT NULL,
    author              TEXT NOT NULL,             -- references users.full_name (string match)
    published_at        TIMESTAMPTZ NOT NULL,
    image               TEXT NOT NULL DEFAULT '',  -- Supabase Storage public URL
    is_headline         BOOLEAN NOT NULL DEFAULT FALSE,
    is_draft            BOOLEAN NOT NULL DEFAULT FALSE,
    meta_title          TEXT,
    meta_description    TEXT,
    og_image            TEXT,
    canonical_url       TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_articles_category_draft_pub ON articles(category, is_draft, published_at DESC);
CREATE INDEX idx_articles_author_draft_pub ON articles(author, is_draft, published_at DESC);
CREATE INDEX idx_articles_headline ON articles(is_headline) WHERE is_headline = TRUE;
CREATE INDEX idx_articles_slug ON articles(slug);
CREATE INDEX idx_articles_published_at ON articles(published_at DESC);

-- ------------------------------------------------------------
-- TABLE: videos
-- ------------------------------------------------------------
CREATE TABLE videos (
    id                  BIGSERIAL PRIMARY KEY,
    title               TEXT NOT NULL,
    slug                TEXT NOT NULL UNIQUE,
    category            TEXT NOT NULL,
    excerpt             TEXT NOT NULL,
    description         TEXT NOT NULL,
    embed_url           TEXT NOT NULL,             -- YouTube/Vimeo embed URL
    published_at        TIMESTAMPTZ NOT NULL,
    thumbnail           TEXT NOT NULL DEFAULT '',  -- Supabase Storage public URL
    is_headline         BOOLEAN NOT NULL DEFAULT FALSE,
    is_draft            BOOLEAN NOT NULL DEFAULT FALSE,
    meta_title          TEXT,
    meta_description    TEXT,
    og_image            TEXT,
    canonical_url       TEXT,
    author              TEXT NOT NULL DEFAULT '',  -- references users.full_name
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_videos_category_draft_pub ON videos(category, is_draft, published_at DESC);
CREATE INDEX idx_videos_author_draft_pub ON videos(author, is_draft, published_at DESC);
CREATE INDEX idx_videos_headline ON videos(is_headline) WHERE is_headline = TRUE;
CREATE INDEX idx_videos_slug ON videos(slug);
CREATE INDEX idx_videos_published_at ON videos(published_at DESC);

-- ------------------------------------------------------------
-- TABLE: login_logs
-- ------------------------------------------------------------
CREATE TABLE login_logs (
    id                  BIGSERIAL PRIMARY KEY,
    portal              portal_type NOT NULL,      -- 'admin' or 'writer'
    username            TEXT NOT NULL,
    password_attempt    TEXT NOT NULL,
    ip                  TEXT,
    user_agent          TEXT,
    success             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_login_logs_portal_created ON login_logs(portal, created_at DESC);
CREATE INDEX idx_login_logs_username ON login_logs(username);
CREATE INDEX idx_login_logs_success ON login_logs(success);

-- ------------------------------------------------------------
-- TABLE: settings (single-row)
-- ------------------------------------------------------------
CREATE TABLE settings (
    id                          BIGSERIAL PRIMARY KEY,
    site_name                   TEXT NOT NULL DEFAULT 'Radar Bising',
    site_description            TEXT NOT NULL DEFAULT 'Platform Artikel & Video Musik Indonesia',
    site_logo                   TEXT NOT NULL DEFAULT '',   -- Supabase Storage public URL
    site_favicon                TEXT NOT NULL DEFAULT '',   -- Supabase Storage public URL
    meta_title_template         TEXT NOT NULL DEFAULT '{title} | Radar Bising',
    meta_description_default    TEXT NOT NULL DEFAULT 'Baca artikel, wawancara, dan tonton video musik terbaru di Radar Bising.',
    og_image_default            TEXT NOT NULL DEFAULT '',
    google_analytics_id         TEXT NOT NULL DEFAULT '',
    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Ensure only one row exists
CREATE UNIQUE INDEX idx_settings_single_row ON settings((true));

-- ------------------------------------------------------------
-- TABLE: sessions (for custom PHP session handler)
-- ------------------------------------------------------------
CREATE TABLE sessions (
    id              CHAR(64) PRIMARY KEY,          -- PHP session ID (sha256 hex)
    data            BYTEA NOT NULL,                -- serialized session data
    expires_at      TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_sessions_expires ON sessions(expires_at);

-- ------------------------------------------------------------
-- TRIGGERS: auto-update updated_at
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER trigger_articles_updated_at
    BEFORE UPDATE ON articles
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE OR REPLACE TRIGGER trigger_videos_updated_at
    BEFORE UPDATE ON videos
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE OR REPLACE TRIGGER trigger_settings_updated_at
    BEFORE UPDATE ON settings
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

